#!/usr/bin/env node
'use strict';
// Bundle the editable sources without a web server or third-party build package.
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const vm=require('node:vm');
const {execFileSync}=require('node:child_process');
const root=path.resolve(__dirname,'..'),output=path.join(root,'standalone');
const check=process.argv.includes('--check'),sources={};
const sha=data=>crypto.createHash('sha256').update(data).digest('hex');
function read(name){
 const file=path.resolve(root,name);
 if(!file.startsWith(root+path.sep))throw Error('Asset escapes project: '+name);
 const data=fs.readFileSync(file);sources[name.replaceAll(path.sep,'/')]=sha(data);return data;
}
const mime={'.svg':'image/svg+xml','.png':'image/png','.woff2':'font/woff2'};
function dataURL(name){const type=mime[path.extname(name)];if(!type)throw Error('Unknown embedded asset type: '+name);return `data:${type};base64,${read(name).toString('base64')}`;}
const localName=ref=>ref.split(/[?#]/,1)[0];
execFileSync('rtk',['proxy',process.execPath,path.join(root,'scripts/build-routing-data.cjs'),'--check'],{stdio:'inherit'});
execFileSync('rtk',['proxy',process.execPath,path.join(root,'scripts/update-cache-versions.cjs'),...(check?['--check']:[])],{stdio:'inherit'});
let html=read('index.html').toString('utf8');
// The standalone contains every dependency and must not poll the web release.
const bootstrap=/<script\s+id="cache-bootstrap"[^>]*>[\s\S]*?<\/script>\s*/i;
if(!bootstrap.test(html))throw Error('Cache bootstrap is missing from the source entry.');
html=html.replace(bootstrap,'');
const scripts=[];
const shortcutImages=Object.fromEntries(fs.readdirSync(path.join(root,'vendor/shortcuts')).filter(name=>name.endsWith('.svg')).sort().map(name=>[name,dataURL('vendor/shortcuts/'+name)]));
html=html.replace(/<link\b[^>]*>/gi,tag=>{
 const href=tag.match(/\bhref="([^"]+)"/i)?.[1],rel=tag.match(/\brel="([^"]+)"/i)?.[1];
 if(rel==='stylesheet'){
  if(!href||/^(?:[a-z]+:|\/\/)/i.test(href))throw Error('Expected a local stylesheet: '+tag);
  const name=localName(href);
  let css=read(name).toString('utf8').replace(/\/\*[#@]\s*sourceMappingURL=[\s\S]*?\*\//g,'');
  css=css.replace(/url\(\s*(?:(["'])(.*?)\1|([^)]*))\s*\)/gi,(match,quote,quoted,bare)=>{
   const ref=(quoted??bare).trim();if(ref.startsWith('data:')||ref.startsWith('#'))return match;
   if(/^(?:[a-z]+:|\/\/)/i.test(ref))throw Error('Remote CSS asset: '+ref);
   return 'url("'+dataURL(path.posix.join(path.posix.dirname(name),localName(ref)))+'")';
  });
  return `<style data-source="${name}">\n${css.replace(/<\/style/gi,'<\\/style')}\n</style>`;
 }
 if(rel==='icon')return tag.replace(href,dataURL(localName(href)));
 return tag;
});
html=html.replace(/<script\b([^>]*)\bsrc="([^"]+)"([^>]*)>\s*<\/script>/gi,(tag,before,src)=>{
 if(/^(?:[a-z]+:|\/\/)/i.test(src))throw Error('Remote script dependency: '+src);
 const name=localName(src);
 let js=read(name).toString('utf8').replace(/^\/\/[#@]\s*sourceMappingURL=.*$/gm,'');
 if(name==='support-ui.js'){
  const imagePath=`src="vendor/shortcuts/'+image+(window.AccessAdelaideBuildVersion?'?v='+window.AccessAdelaideBuildVersion:'')+'"`,embedded=`src="'+standaloneShortcutImages[image]+'"`;
  if(!js.includes(imagePath)||!js.includes('(() => {'))throw Error('Shortcut image binding changed; update the standalone bundler.');
  js=js.replace('(() => {','(() => {\nconst standaloneShortcutImages='+JSON.stringify(shortcutImages)+';').replace(imagePath,embedded);
 }
 scripts.push(`<script data-source="${name}">\n${js.replace(/<\/script/gi,'<\\/script')}\n</script>`);
 return '';
});
if(!scripts.length||/<script\b[^>]*\bsrc=/i.test(html))throw Error('Unbundled script dependency.');
// Inline scripts execute after the body exists; defer does not apply to inline JS.
html=html.replace(/<\/body>(?=\s*<\/html>\s*$)/i,()=>scripts.join('\n')+'\n</body>');
const noticeFiles=['vendor/MAPLIBRE-LICENSE.txt','vendor/OPENDYSLEXIC-LICENSE.txt','vendor/OPENDYSLEXIC-SOURCES.md',...fs.readdirSync(path.join(root,'vendor/shortcuts')).filter(name=>name.endsWith('.md')).sort().map(name=>'vendor/shortcuts/'+name)];
const notices=Object.fromEntries(noticeFiles.map(name=>[name,read(name).toString('utf8')]));
const manifest={format:1,entry:'index.html',sources:Object.fromEntries(Object.entries(sources).sort(([a],[b])=>a.localeCompare(b)))};
const json=value=>JSON.stringify(value).replace(/</g,'\\u003c');
html=html.replace(/<\/body>(?=\s*<\/html>\s*$)/i,()=>`<script id="standalone-build" type="application/json">${json(manifest)}</script>\n<script id="third-party-notices" type="application/json">${json(notices)}</script>\n</body>`);
html=html.replace('<!DOCTYPE html>','<!DOCTYPE html>\n<!-- Generated by scripts/build-standalone.cjs. Edit the separate source files and rebuild. -->');
let scriptCount=0;
for(const match of html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)){
 if(match[1].includes('application/json')){JSON.parse(match[2]);continue;}
 new vm.Script(match[2],{filename:match[1].match(/data-source="([^"]+)"/)?.[1]||'standalone.js'});scriptCount++;
}
if(scriptCount!==scripts.length)throw Error('Standalone script boundaries changed during bundling.');
const target=path.join(output,'Access_Adelaide.html'),zip=path.join(output,'Access_Adelaide.zip');
if(check){if(!fs.existsSync(target)||fs.readFileSync(target,'utf8')!==html)throw Error('Standalone HTML is stale. Run node scripts/build-standalone.cjs.');}
else{fs.mkdirSync(output,{recursive:true});fs.writeFileSync(target,html);}
// Python's standard library produces a deterministic archive containing one HTML.
const zipScript=`import io, pathlib, sys, zipfile
html, archive, check = pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2]), sys.argv[3] == 'check'
info = zipfile.ZipInfo(html.name, date_time=(1980, 1, 1, 0, 0, 0))
info.compress_type = zipfile.ZIP_DEFLATED
info.create_system = 3
info.external_attr = 0o100644 << 16
buf = io.BytesIO()
with zipfile.ZipFile(buf, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=9) as z:
    z.writestr(info, html.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
data = buf.getvalue()
if check:
    if not archive.exists() or archive.read_bytes() != data:
        raise SystemExit('Standalone ZIP is stale. Run node scripts/build-standalone.cjs.')
else:
    archive.write_bytes(data)
`;
execFileSync('rtk',['proxy','python3','-c',zipScript,target,zip,check?'check':'build'],{stdio:'inherit'});
console.log(`${check?'Verified':'Built'} standalone HTML (${Buffer.byteLength(html)} bytes) and one-file ZIP (${fs.statSync(zip).size} bytes).`);
